-- EduSmart fresh Supabase schema
-- Staff appraisal
-- Generated from src/data. Replaces only tables in schema edusmart.
-- Nested objects and mixed lists are jsonb. Plain lists are Postgres arrays.
-- Demo passwords from src/data are included. Row level security is on and has no policies,
-- so the anon API cannot read these tables. The SQL editor and service_role can.
begin;
create schema if not exists "edusmart";
grant usage on schema "edusmart" to postgres, service_role, authenticated, anon;

-- src/data/staffAppraisalData.ts :: INITIAL_TPAD_STANDARDS (5 rows)
drop table if exists "edusmart"."tpad_standards" cascade;
create table "edusmart"."tpad_standards" (
  "standard_id" text not null,
  "standard_number" bigint not null,
  "standard_title" text not null,
  "sub_standards" text[] not null,
  primary key ("standard_id")
);
comment on table "edusmart"."tpad_standards" is $es$Platform feature pack from src/data/staffAppraisalData.ts export INITIAL_TPAD_STANDARDS. Creating a school starts from this pack. The school then customises its own rows.$es$;
insert into "edusmart"."tpad_standards" ("standard_id", "standard_number", "standard_title", "sub_standards") values
  ($es$tpad-std-1$es$, 1, $es$Professional Knowledge & Application$es$, array[$es$Comprehensive preparation and updating of Schemes of Work from KICD curriculum designs$es$, $es$Development of competency-focused Lesson Plans with clear specific learning outcomes$es$, $es$Integration of teaching-learning resources including digital tools and concrete apparatus$es$, $es$Adherence to lesson timetables, work entry records, and continuous syllabus pacing$es$]::text[]),
  ($es$tpad-std-2$es$, 2, $es$Comprehensive Learning Environment$es$, array[$es$Safe, orderly, and learner-centered classroom physical/virtual environment$es$, $es$Effective classroom management, gender equity, and pastoral inclusion$es$, $es$Display of dynamic curriculum talking walls, charts, and learner exhibits$es$, $es$Clear learner conduct standards and positive behavioral reinforcement$es$]::text[]),
  ($es$tpad-std-3$es$, 3, $es$Teacher Professional Development (TPD)$es$, array[$es$Identification of personal pedagogical gaps and participation in TPD modules$es$, $es$Attendance at school-based subject department panels, workshops, and KICD seminars$es$, $es$Continuous ICT capacity building and incorporation of educational technology$es$, $es$Mentorship of student teachers, novice faculty, and peer lesson co-planning$es$]::text[]),
  ($es$tpad-std-4$es$, 4, $es$Learner Protection, Safety, Well-Being & Values$es$, array[$es$Adherence to Children Act 2022, child safeguarding, and zero corporal punishment$es$, $es$Early detection and supportive referral of vulnerable, distressed, or unwell learners$es$, $es$Integration of core CBC values (integrity, patriotism, love, peace, respect)$es$, $es$Active supervision during school break times, laboratory sessions, and games$es$]::text[]),
  ($es$tpad-std-5$es$, 5, $es$Teacher Professional Conduct & Performance$es$, array[$es$Punctuality in class reporting, morning assemblies, and scheduled teacher-on-duty rosters$es$, $es$Timely assessment marking, constructive feedback, and submission of student marks$es$, $es$Professional communication and collaborative partnership with parents and guardians$es$, $es$Compliance with Teachers Service Commission (TSC) Code of Regulation and Ethics$es$]::text[]);
alter table "edusmart"."tpad_standards" enable row level security;

-- src/data/staffAppraisalData.ts :: INITIAL_STAFF_APPRAISALS (5 rows)
drop table if exists "edusmart"."staff_appraisals" cascade;
create table "edusmart"."staff_appraisals" (
  "id" text not null,
  "teacher_id" text not null,
  "teacher_name" text not null,
  "tsc_number" text not null,
  "designation" text not null,
  "department" text not null,
  "subjects_taught" text[] not null,
  "term" bigint not null,
  "academic_year" bigint not null,
  "status" text not null,
  "standards" jsonb not null,
  "lesson_observations" jsonb not null,
  "tpd_gap_identified" text not null,
  "target_interventions" text not null,
  "appraiser_name" text not null,
  "appraiser_role" text not null,
  "countersigning_officer_name" text,
  "overall_percentage" bigint not null,
  "performance_grade" text not null,
  "teacher_comments" text not null,
  "appraiser_general_remarks" text not null,
  "countersigning_remarks" text,
  "submitted_at" text not null,
  "completed_at" text,
  "countersigned_at" text,
  "created_at" text not null,
  "school_id" text not null,
  primary key ("id")
);
comment on table "edusmart"."staff_appraisals" is $es$School data from src/data/staffAppraisalData.ts export INITIAL_STAFF_APPRAISALS. school_id is the school. A school customises these rows on its own.$es$;
insert into "edusmart"."staff_appraisals" ("id", "teacher_id", "teacher_name", "tsc_number", "designation", "department", "subjects_taught", "term", "academic_year", "status", "standards", "lesson_observations", "tpd_gap_identified", "target_interventions", "appraiser_name", "appraiser_role", "countersigning_officer_name", "overall_percentage", "performance_grade", "teacher_comments", "appraiser_general_remarks", "countersigning_remarks", "submitted_at", "completed_at", "countersigned_at", "created_at", "school_id") values
  ($es$appraisal-001$es$, $es$u-teacher-01$es$, $es$Ms. Sarah Mwangi$es$, $es$TSC/489211/KE$es$, $es$Senior Teacher II / Head of Mathematics$es$, $es$Mathematics & Computational Sciences$es$, array[$es$Mathematics$es$]::text[], 2, 2026, $es$countersigned$es$, $es$[{"standardId":"tpad-std-1","standardNumber":1,"standardTitle":"Professional Knowledge & Application","subStandards":["Comprehensive preparation of Schemes of Work","Competency-focused Lesson Plans"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Schemes of Work for Term 2 submitted in Week 1; 100% lesson plans verified with manipulative aids for fractions.","appraiserRemarks":"Flawless pedagogical documentation. Exemplary use of concrete realia."},{"standardId":"tpad-std-2","standardNumber":2,"standardTitle":"Comprehensive Learning Environment","subStandards":["Safe, orderly classroom climate","Display of dynamic talking walls"],"selfScore":4,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Interactive math talking wall featuring fraction strips and geometric origami; zero disciplinary referrals.","appraiserRemarks":"Classroom displays actively reinforce learner curiosity and self-assessment."},{"standardId":"tpad-std-3","standardNumber":3,"standardTitle":"Teacher Professional Development (TPD)","subStandards":["Participation in TPD modules","Continuous ICT integration"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Completed CEMASTEA Module 3 on Inquiry-Based Math Instruction; conducted peer workshop for junior school math teachers.","appraiserRemarks":"Good departmental initiative in cascading CEMASTEA techniques."},{"standardId":"tpad-std-4","standardNumber":4,"standardTitle":"Learner Protection, Safety, Well-Being & Values","subStandards":["Child safeguarding compliance","Integration of core CBC values"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Coordinated math clinic for struggling learners; established supportive peer-buddy groups.","appraiserRemarks":"Commendable empathy and pastoral attentiveness."},{"standardId":"tpad-std-5","standardNumber":5,"standardTitle":"Teacher Professional Conduct & Performance","subStandards":["Punctuality and duty rosters","Timely assessment marking"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Assigned as Teacher-on-Duty Week 3; 100% daily morning briefing attendance; CAT marks submitted 2 days ahead of deadline.","appraiserRemarks":"Model professional conduct and institutional dedication."}]$es$::jsonb, $es$[{"id":"obs-01","date":"2026-10-03","subject":"Mathematics","grade":4,"stream":"East","strandOrTopic":"Fractions & Equivalence Models","observationScore":96,"strengths":["High learner engagement using physical paper strip folding","Clear formative questioning techniques targeting critical thinking","Excellent pace distribution across introduction, inquiry, and conclusion"],"areasForGrowth":["Extend challenge problems for learners who master equivalent fractions ahead of class"],"observerName":"Mrs. Beatrice Omari (Curriculum Coordinator)"}]$es$::jsonb, $es$Advanced digital spreadsheet modelling for Junior Secondary Grade 7 mathematics.$es$, $es$Enroll in upcoming KICD Digital Mathematics Teaching Practicum in Term 3.$es$, $es$Mr. James Wafula (Deputy Head Teacher)$es$, $es$Deputy Head Teacher$es$, $es$Dr. Arthur Onyango (Head Teacher)$es$, 96, $es$Exemplary (90-100%)$es$, $es$Grateful for constructive feedback on fraction realia. Looking forward to expanding digital math lessons.$es$, $es$Consistently exceptional instructor who elevates school academic standards.$es$, $es$Appraisal ratified by Head Teacher. Commended for exemplary devotion to learner outcome excellence.$es$, $es$2026-10-05T08:00:00Z$es$, $es$2026-10-07T14:30:00Z$es$, $es$2026-10-08T10:15:00Z$es$, $es$2026-10-01T09:00:00Z$es$, $es$tenant-riara$es$),
  ($es$appraisal-002$es$, $es$u-teacher-02$es$, $es$Mr. David Omondi$es$, $es$TSC/512940/KE$es$, $es$Instructor / Science Faculty Lead$es$, $es$Pure & Integrated Sciences$es$, array[$es$Integrated Science$es$]::text[], 2, 2026, $es$completed$es$, $es$[{"standardId":"tpad-std-1","standardNumber":1,"standardTitle":"Professional Knowledge & Application","subStandards":["Comprehensive preparation of Schemes of Work","Competency-focused Lesson Plans"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Executed 6 laboratory practical sessions on capillary action and natural plant indicators; schemes up to date.","appraiserRemarks":"Hands-on practical experiments executed safely and effectively."},{"standardId":"tpad-std-2","standardNumber":2,"standardTitle":"Comprehensive Learning Environment","subStandards":["Safe, orderly classroom climate","Display of dynamic talking walls"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Science lab apparatus clearly demarcated; safety eye wash stations inspected weekly.","appraiserRemarks":"Good laboratory hygiene and chemical storage protocols."},{"standardId":"tpad-std-3","standardNumber":3,"standardTitle":"Teacher Professional Development (TPD)","subStandards":["Participation in TPD modules","Continuous ICT integration"],"selfScore":3,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Integrated EduSmart Virtual Science Lab simulations into Grade 8 chemistry lessons.","appraiserRemarks":"Notable improvement in leveraging digital laboratory workbench tools."},{"standardId":"tpad-std-4","standardNumber":4,"standardTitle":"Learner Protection, Safety, Well-Being & Values","subStandards":["Child safeguarding compliance","Integration of core CBC values"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Strict enforcement of lab PPE coats and goggles; environmental cleanup of biological specimens.","appraiserRemarks":"High emphasis on laboratory hazard mitigation."},{"standardId":"tpad-std-5","standardNumber":5,"standardTitle":"Teacher Professional Conduct & Performance","subStandards":["Punctuality and duty rosters","Timely assessment marking"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Regular duty supervision; marks recorded and uploaded in timely fashion.","appraiserRemarks":"Dependable and cooperative faculty member."}]$es$::jsonb, $es$[{"id":"obs-02","date":"2026-10-06","subject":"Integrated Science","grade":8,"stream":"all","strandOrTopic":"Natural Acid-Base Indicators & pH Testing","observationScore":88,"strengths":["Effective guided discovery using crushed hibiscus petals","Good safety reinforcement before distributing chemical reagents","Active collaborative team dynamics in laboratory groups"],"areasForGrowth":["Ensure all groups complete written hypothesis prior to beginning laboratory manipulation"],"observerName":"Mrs. Beatrice Omari (Curriculum Coordinator)"}]$es$::jsonb, $es$Formative rubric development for laboratory psychomotor skills.$es$, $es$Collaborate with Curriculum Coordinator on CBA Performance Task rubrics.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$Curriculum Coordinator$es$, $es$Dr. Arthur Onyango (Head Teacher)$es$, 88, $es$Very Good (80-89%)$es$, $es$Enjoyed integrating the virtual lab alongside physical apparatus. Will standardize lab rubrics.$es$, $es$Solid STEM educator with strong commitment to learner practical proficiency.$es$, null, $es$2026-10-06T10:00:00Z$es$, $es$2026-10-09T11:00:00Z$es$, null, $es$2026-10-02T08:30:00Z$es$, $es$tenant-riara$es$),
  ($es$appraisal-003$es$, $es$u-teacher-03$es$, $es$Mr. John Kamau$es$, $es$TSC/630144/KE$es$, $es$Senior Faculty / ICT & Computing Lead$es$, $es$Technical & Applied Sciences$es$, array[$es$Computer Studies$es$]::text[], 2, 2026, $es$countersigned$es$, $es$[{"standardId":"tpad-std-1","standardNumber":1,"standardTitle":"Professional Knowledge & Application","subStandards":["Comprehensive preparation of Schemes of Work","Competency-focused Lesson Plans"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Authored complete Term 2 Scratch Algorithm challenges and spreadsheet financial templates.","appraiserRemarks":"Exceptional mastery of junior secondary computing designs."},{"standardId":"tpad-std-2","standardNumber":2,"standardTitle":"Comprehensive Learning Environment","subStandards":["Safe, orderly classroom climate","Display of dynamic talking walls"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Computer Lab projected environment maintained with zero workstation downtime; keyboard shortcut posters installed.","appraiserRemarks":"Computer Lab is in world-class instructional condition."},{"standardId":"tpad-std-3","standardNumber":3,"standardTitle":"Teacher Professional Development (TPD)","subStandards":["Participation in TPD modules","Continuous ICT integration"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Conducted whole-school staff training on Scratch coding projection and digital attendance tracking.","appraiserRemarks":"A key school-wide catalyst for ICT adoption across disciplines."},{"standardId":"tpad-std-4","standardNumber":4,"standardTitle":"Learner Protection, Safety, Well-Being & Values","subStandards":["Child safeguarding compliance","Integration of core CBC values"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Strict digital safety protocols in place; SafeSearch browser and content firewalls configured for all student terminals.","appraiserRemarks":"