  ($es$appraisal-004$es$, $es$u-teacher-04$es$, $es$Mrs. Grace Njeri$es$, $es$TSC/467812/KE$es$, $es$Senior Teacher / Workshop Administrator$es$, $es$Pretechnical & Creative Arts$es$, array[$es$Pretechnical Education$es$]::text[], 2, 2026, $es$appraisal_meeting_pending$es$, $es$[{"standardId":"tpad-std-1","standardNumber":1,"standardTitle":"Professional Knowledge & Application","subStandards":["Comprehensive preparation of Schemes of Work","Competency-focused Lesson Plans"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Technical drawing plates compiled; workshop tool maintenance logs kept up to date.","appraiserRemarks":"Strong technical accuracy and drafting competency."},{"standardId":"tpad-std-2","standardNumber":2,"standardTitle":"Comprehensive Learning Environment","subStandards":["Safe, orderly classroom climate","Display of dynamic talking walls"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Workshop floor hazard markings freshly repainted; safety goggles sterilized after each period.","appraiserRemarks":"Top-tier workshop safety culture."},{"standardId":"tpad-std-3","standardNumber":3,"standardTitle":"Teacher Professional Development (TPD)","subStandards":["Participation in TPD modules","Continuous ICT integration"],"selfScore":3,"appraiserScore":3,"agreedScore":3,"evidenceDescription":"Attended regional TVET transition workshop.","appraiserRemarks":"Encouraged to integrate more CAD/digital 3D drafting into junior school lessons."},{"standardId":"tpad-std-4","standardNumber":4,"standardTitle":"Learner Protection, Safety, Well-Being & Values","subStandards":["Child safeguarding compliance","Integration of core CBC values"],"selfScore":5,"appraiserScore":5,"agreedScore":5,"evidenceDescription":"Zero workshop incidents recorded; excellent learner discipline regarding cutting blades.","appraiserRemarks":"Flawless safety oversight."},{"standardId":"tpad-std-5","standardNumber":5,"standardTitle":"Teacher Professional Conduct & Performance","subStandards":["Punctuality and duty rosters","Timely assessment marking"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Consistent punctuality and reliable equipment inventory management.","appraiserRemarks":"Very dependable senior teacher."}]$es$::jsonb, $es$[{"id":"obs-04","date":"2026-10-05","subject":"Pretechnical Education","grade":8,"stream":"all","strandOrTopic":"Workshop Tool Station Inspection & Rust Prevention","observationScore":90,"strengths":["Step-by-step practical demonstration on linseed oil application","Strict enforcement of safety zone walkways","Individual checks on learner grip technique"],"areasForGrowth":["Introduce digital stopwatches for measuring learner station transition efficiency"],"observerName":"Mr. James Wafula (Deputy Head Teacher)"}]$es$::jsonb, $es$Digital CAD software integration for Junior Secondary isometric drawing.$es$, $es$Pair with Mr. Kamau for sketchup / online CAD modules in Computer Lab.$es$, $es$Mr. James Wafula (Deputy Head Teacher)$es$, $es$Deputy Head Teacher$es$, null, 86, $es$Very Good (80-89%)$es$, $es$Meeting scheduled with Deputy Head to finalize agreed ratings and submit to Head Teacher.$es$, $es$Robust technical instructor with impeccable safety records.$es$, null, $es$2026-10-05T11:00:00Z$es$, null, null, $es$2026-10-02T11:00:00Z$es$, $es$tenant-riara$es$),
  ($es$appraisal-005$es$, $es$u-teacher-05$es$, $es$Mr. Patrick Mutiso$es$, $es$TSC/582910/KE$es$, $es$Faculty / Arts & Music Lead$es$, $es$Creative Arts & Sports$es$, array[$es$Creative Arts$es$]::text[], 2, 2026, $es$submitted_for_appraisal$es$, $es$[{"standardId":"tpad-std-1","standardNumber":1,"standardTitle":"Professional Knowledge & Application","subStandards":["Comprehensive preparation of Schemes of Work","Competency-focused Lesson Plans"],"selfScore":4,"appraiserScore":3,"agreedScore":3,"evidenceDescription":"Indigenous fiber weaving schemes prepared; lesson plans updated for Grade 5.","appraiserRemarks":"Pacing lag noted in Week 5; catch-up remedial sessions required."},{"standardId":"tpad-std-2","standardNumber":2,"standardTitle":"Comprehensive Learning Environment","subStandards":["Safe, orderly classroom climate","Display of dynamic talking walls"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Art studio displays learner placemats and traditional Kenyan beadwork exhibits.","appraiserRemarks":"Vibrant, colorful cultural studio atmosphere."},{"standardId":"tpad-std-3","standardNumber":3,"standardTitle":"Teacher Professional Development (TPD)","subStandards":["Participation in TPD modules","Continuous ICT integration"],"selfScore":3,"appraiserScore":3,"agreedScore":3,"evidenceDescription":"Attended county cultural music festival adjudication training.","appraiserRemarks":"Recommended to document digital photographic portfolios of learner artworks."},{"standardId":"tpad-std-4","standardNumber":4,"standardTitle":"Learner Protection, Safety, Well-Being & Values","subStandards":["Child safeguarding compliance","Integration of core CBC values"],"selfScore":4,"appraiserScore":4,"agreedScore":4,"evidenceDescription":"Safe storage of craft cutting instruments and non-toxic dyes.","appraiserRemarks":"Safe material handling observed."},{"standardId":"tpad-std-5","standardNumber":5,"standardTitle":"Teacher Professional Conduct & Performance","subStandards":["Punctuality and duty rosters","Timely assessment marking"],"selfScore":3,"appraiserScore":3,"agreedScore":3,"evidenceDescription":"Conducts choir practice punctually; working on speeding up mark uploads.","appraiserRemarks":"Needs to ensure gradebook submissions meet official administrative timelines."}]$es$::jsonb, $es$[{"id":"obs-05","date":"2026-10-07","subject":"Creative Arts","grade":5,"stream":"North","strandOrTopic":"Indigenous Cardboard Loom Weaving","observationScore":78,"strengths":["Excellent cultural storytelling regarding indigenous sisal fiber extraction","Learners excited and engaged in tactile yarn threading"],"areasForGrowth":["Demonstrate edge tension control more clearly to prevent hour-glassing of placemats","Accelerate pacing to cover remaining strands on schedule"],"observerName":"Mrs. Beatrice Omari (Curriculum Coordinator)"}]$es$::jsonb, $es$Syllabus pacing acceleration and formative rubric calibration for psychomotor crafts.$es$, $es$Attend Curriculum Coordinator coaching sessions on CBC pacing recovery.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$Curriculum Coordinator$es$, null, 74, $es$Good (60-79%)$es$, $es$Working diligently on catch-up weaving schedule.$es$, $es$Creative teacher with strong cultural passion. Pacing support in progress.$es$, null, $es$2026-10-07T12:00:00Z$es$, null, null, $es$2026-10-03T09:00:00Z$es$, $es$tenant-riara$es$);
